INSERT INTO public.qb_questions (subject_id, difficulty, question_type, question_text, options, correct_answer, explanation, points, tags) VALUES
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'A garment''s fabric consumption is 1.6 meters, and fabric costs $4 per meter. If trims (buttons, zipper, labels) cost $0.80 per garment and labor (SAM × rate) costs $1.20 per garment, what is the approximate total cost to make one garment?', '["$8.40","$6.40","$4.00","$2.00"]'::jsonb, '$8.40', 'Fabric cost = 1.6 × $4 = $6.40. Total cost = fabric + trims + labor = $6.40 + $0.80 + $1.20 = $8.40.', 2, '{"garment-cost-calc"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'A garment''s fabric consumption is 1.2 meters at $5/meter, trims cost $0.60, and labor costs $1.00. What is the approximate total cost to make one garment?', '["$7.60","$6.00","$1.60","$5.00"]'::jsonb, '$7.60', 'Fabric cost = 1.2 × $5 = $6.00. Total cost = $6.00 + $0.60 + $1.00 = $7.60.', 2, '{"garment-cost-calc"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'A factory produces 2,400 garments per day across 3 sewing lines. What is the average daily output per line?', '["800 garments","2,400 garments","3 garments","7,200 garments"]'::jsonb, '800 garments', 'Average output per line = total output ÷ number of lines = 2,400 ÷ 3 = 800 garments.', 1, '{"line-output-average-calc"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'An order requires 15,000 garments to be produced in 12 working days. What is the average daily production target?', '["1,250 garments","15,000 garments","12 garments","180,000 garments"]'::jsonb, '1,250 garments', 'Daily target = total order quantity ÷ number of days = 15,000 ÷ 12 = 1,250 garments.', 1, '{"daily-target-calc"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'basic', 'multiple_choice', 'A factory''s rejection rate from final AQL inspection is 3% on an order of 20,000 garments. Approximately how many garments are expected to be rejected?', '["600 garments","3 garments","6,667 garments","60 garments"]'::jsonb, '600 garments', 'Expected rejects = rejection rate × total order = 0.03 × 20,000 = 600 garments.', 1, '{"rejection-rate-calc"}'::text[]),
('44444444-4444-4444-4444-444444444444', 'intermediate', 'multiple_choice', 'A garment factory''s target is 90% efficiency, but the line is currently running at 72% actual efficiency. What percentage of the target efficiency is currently being achieved?', '["80%","18%","72%","90%"]'::jsonb, '80%', 'Percentage of target achieved = (actual efficiency / target efficiency) × 100 = (72 / 90) × 100 = 80%.', 2, '{"efficiency-target-calc"}'::text[]);
